package cn.sixnine.filmlog;
import android.app.Instrumentation;
import android.os.Bundle;
import android.view.*;
import android.view.accessibility.*;
import java.util.*;

public final class ContactSheetAccessibilityInstrumentation extends Instrumentation {
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){waitForIdleSync();Bundle out=new Bundle();try{android.content.Context context=getTargetContext();check(context.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolation");try(LogStore logs=new LogStore(context)){ScanStore files=new ScanStore(context,logs);ArrayList<LogStore.Shot> shots=new ArrayList<>();for(int frame:new int[]{8,1,3}){LogStore.Shot shot=new LogStore.Shot();shot.frame=frame;shot.id=UUID.randomUUID().toString();shots.add(shot);}String third=shots.get(2).id,eighth=shots.get(0).id;ArrayList<ScanStore.Scan> images=new ArrayList<>();ScanStore.Scan scan=new ScanStore.Scan();scan.id=UUID.randomUUID().toString();scan.shotId=third;images.add(scan);ArrayList<String> opened=new ArrayList<>();runOnMainSync(()->{ContactSheet sheet=new ContactSheet(context,shots,images,files,opened::add);sheet.measure(View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));sheet.layout(0,0,sheet.getMeasuredWidth(),sheet.getMeasuredHeight());AccessibilityNodeProvider nodes=sheet.getAccessibilityNodeProvider();AccessibilityNodeInfo root=nodes.createAccessibilityNodeInfo(AccessibilityNodeProvider.HOST_VIEW_ID);check(root.getChildCount()==3&&root.getCollectionInfo().getColumnCount()==5,"real exposure count and five-column collection");root.recycle();AccessibilityNodeInfo first=nodes.createAccessibilityNodeInfo(1),second=nodes.createAccessibilityNodeInfo(2);check(first.getText().toString().contains("曝光 1")&&first.getText().toString().contains("尚无扫描"),"sorted first frame with empty scan");check(second.getText().toString().contains("曝光 3")&&second.getText().toString().contains("已关联扫描"),"frame gaps don't shift associations");android.graphics.Rect box=new android.graphics.Rect();second.getBoundsInParent(box);check(box.left==120&&box.right==240,"virtual bounds match second visual cell");first.recycle();second.recycle();check(nodes.performAction(2,AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,null),"virtual focus accepted");AccessibilityNodeInfo focused=nodes.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY);check(focused.isAccessibilityFocused()&&focused.getText().toString().contains("曝光 3"),"focus identifies exact exposure");focused.recycle();check(nodes.performAction(2,AccessibilityNodeInfo.ACTION_CLICK,null)&&opened.get(0).equals(third),"virtual activation opens selected exposure");check(nodes.performAction(2,AccessibilityNodeInfo.ACTION_CLEAR_ACCESSIBILITY_FOCUS,null)&&nodes.findFocus(AccessibilityNodeInfo.FOCUS_ACCESSIBILITY)==null,"focus clears");sheet.onKeyDown(KeyEvent.KEYCODE_MOVE_END,new KeyEvent(0,KeyEvent.KEYCODE_MOVE_END));sheet.onKeyDown(KeyEvent.KEYCODE_DPAD_RIGHT,new KeyEvent(0,KeyEvent.KEYCODE_DPAD_RIGHT));sheet.onKeyDown(KeyEvent.KEYCODE_ENTER,new KeyEvent(0,KeyEvent.KEYCODE_ENTER));check(opened.get(1).equals(eighth),"keyboard last-frame boundary and activation");check(nodes.createAccessibilityNodeInfo(99)==null&&!nodes.performAction(99,AccessibilityNodeInfo.ACTION_CLICK,null),"invalid virtual ID rejected");});}
        out.putString("stream","PASS: real-frame virtual grid, sorted/gapped frame mapping, scan descriptions, exact bounds, accessibility focus/click/clear, keyboard end boundary, invalid IDs\n");finish(-1,out);
    }catch(Throwable error){out.putString("stream",android.util.Log.getStackTraceString(error));finish(0,out);}}
}
